<article class="book-detail"><div class="book-cover"><?php if(!empty($b['cover_path'])):?><img src="/uploads/<?=e($b['cover_path'])?>" alt="<?=e($b['title'])?>"><?php else:?><span>📚</span><?php endif;?></div><div class="book-summary"><span class="eyebrow">BOOK · OMH LIBRARY</span><h1><?=e($b['title'])?></h1><p class="author-line">مؤلف: <?php if($b['author_id']):?><a href="/author?id=<?=$b['author_id']?>"><?=e($b['author'])?></a><?php else:?>—<?php endif;?></p><div class="chips"><?php foreach($cats as $c):?><a href="/category?id=<?=$c['id']?>"><?=e($c['name'])?></a><?php endforeach;?></div><div class="meta"><span>زبان: <?=e($b['language_code']?:'—')?></span><span>جلد: <?=e($b['volumes']?:'—')?></span><span>صفحات: <?=e($b['pages']?:'—')?></span><span>سال نشر: <?=e($b['publication_year']?:'—')?></span><span>ناشر: <?=e($b['publisher']?:'—')?></span><span>بازدید: <?=number_format($b['views'])?></span><span>دانلود: <?=number_format($b['downloads'])?></span></div><?php foreach([['مترجم',$b['translator']],['منبع',$b['source_name']],['منبع خارجی',$b['source_url']]] as $m):if($m[1]):?><p class="book-field"><b><?=e($m[0])?>:</b> <?php if($m[0]==='منبع خارجی'):?><a href="<?=e($m[1])?>" target="_blank" rel="noopener noreferrer">مشاهده منبع</a><?php else:?><?=e($m[1])?><?php endif;?></p><?php endif;endforeach;?><div class="book-actions"><?php if(!empty($vols[0]['file_path'])||!empty($vols[0]['external_url'])):?><a class="btn" href="/download?id=<?=$vols[0]['id']?>">⬇ دانلود جلد اول</a><?php endif;?><button class="btn secondary" type="button" onclick="navigator.share?.({title:document.title,url:location.href})">↗ اشتراک‌گذاری</button></div></div></article>
<section class="prose"><h2>معرفی کتاب</h2><p><?=nl2br(e($b['description']?:'معرفی این اثر هنوز توسط مدیریت تکمیل نشده است.'))?></p><?php if($b['full_description']):?><h2>شرح و توضیحات کامل</h2><p><?=nl2br(e($b['full_description']))?></p><?php endif;?></section>
<section class="prose"><div class="section-head"><div><span class="section-kicker">نسخه‌ها</span><h2>جلدها و دانلود</h2></div></div><div class="volumes"><?php foreach($vols as $v):?><div><div><strong>جلد <?=e($v['volume_no'])?></strong><span><?=e($v['volume_title']?:'جلد '.$v['volume_no'])?></span><?php if($v['pages']):?><small><?=number_format($v['pages'])?> صفحه</small><?php endif;?></div><div class="volume-actions"><?php if($v['file_path']):?><a href="/reader?id=<?=$v['id']?>">مطالعه</a><?php endif;?><?php if($v['file_path']||$v['external_url']):?><a class="btn" href="/download?id=<?=$v['id']?>">دانلود</a><?php else:?><small>فایل هنوز اضافه نشده</small><?php endif;?></div></div><?php endforeach;?></div></section>
<?php if($relations):?><section><div class="section-head"><div><span class="section-kicker">روابط علمی</span><h2>شرح‌ها، حواشی و آثار مرتبط</h2></div></div><div class="author-grid"><?php foreach($relations as $r):?><a href="/book?id=<?=$r['id']?>"><strong><?=e($r['title'])?></strong><small><?=e(['commentary'=>'شرح','annotation'=>'حاشیه/تعلیقه','volume'=>'نسخه/جلد','related'=>'مرتبط'][$r['relation_type']]??'مرتبط')?> · <?=e($r['author']??'')?></small></a><?php endforeach;?></div></section><?php endif;?>
<?php if($authorBooks):?><section><div class="section-head"><div><span class="section-kicker">مؤلف</span><h2>دیگر آثار <?=e($b['author'])?></h2></div><a class="text-link" href="/author?id=<?=$b['author_id']?>">زندگی‌نامه ←</a></div><div class="author-grid"><?php foreach($authorBooks as $r):?><a href="/book?id=<?=$r['id']?>"><strong><?=e($r['title'])?></strong></a><?php endforeach;?></div></section><?php endif;?>
<?php if($related):?><section><div class="section-head"><h2>کتاب‌های مرتبط</h2></div><div class="author-grid"><?php foreach($related as $r):?><a href="/book?id=<?=$r['id']?>"><strong><?=e($r['title'])?></strong><small><?=e($r['author']??'')?></small></a><?php endforeach;?></div></section><?php endif; ?>
